,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Prefill From Profile'
,p_static_id=>'prefill-from-profile'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for u in (select * from fj_users where id = fj_flow.current_user_id) loop',
'  :P3_FIRST_NAME := nvl(:P3_FIRST_NAME, u.first_name);',
'  :P3_LAST_NAME  := nvl(:P3_LAST_NAME, u.last_name);',
'  :P3_EMAIL      := nvl(:P3_EMAIL, u.email);',
'  :P3_LOCATION   := nvl(:P3_LOCATION, u.location);',
'  :P3_PHONE      := nvl(:P3_PHONE, u.phone);',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9459000000000000323
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9459000000000000321)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save Application'
,p_static_id=>'save-application'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_blob     blob;',
'  l_filename varchar2(400);',
'  l_mime     varchar2(255);',
'  l_user_id  number := fj_flow.current_user_id;',
'  l_app_id   number;',
'  l_n        number;',
'  l_title    fj_jobs.title%type;',
'begin',
'  select count(*) into l_n from fj_applications where job_id = to_number(:P3_JOB_ID) and user_id = l_user_id;',
'  if l_n > 0 then',
'    raise_application_error(-20001, ''You have already applied for this job. Track it under My Applications.'');',
'  end if;',
'  select count(*) into l_n from fj_jobs where id = to_number(:P3_JOB_ID) and is_filled = ''Y'';',
'  if l_n > 0 then',
'    raise_application_error(-20001, ''Sorry, this position has already been filled.'');',
'  end if;',
'  if :P3_CV is not null then',
'    select blob_content, filename, mime_type',
'      into l_blob, l_filename, l_mime',
'      from apex_application_temp_files',
'     where name = :P3_CV;',
'  end if;',
'  insert into fj_applications (job_id, user_id, first_name, last_name, email, location, phone, cv_blob, cv_filename, cv_mimetype)',
'  values (to_number(:P3_JOB_ID), l_user_id, :P3_FIRST_NAME, :P3_LAST_NAME, lower(:P3_EMAIL), :P3_LOCATION, :P3_PHONE, l_blob, l_filename, l_mime)',
'  returning id into l_app_id;',
'  -- keep the seeker profile up to date for next time',
'  update fj_users set first_name = :P3_FIRST_NAME, last_name = :P3_LAST_NAME, phone = :P3_PHONE, location = :P3_LOCATION',
'   where id = l_user_id;',
'  select title into l_title from fj_jobs where id = to_number(:P3_JOB_ID);',
'  fj_flow.notify(l_app_id, ''Application received'',',
'    ''We have received your application for "'' || l_title || ''". The employer will review it and you will be notified about the next step.'');',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>9459000000000000321
);
end;
