wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9459000000000000421)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Job'
,p_static_id=>'load-job'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for j in (select * from fj_jobs where id = to_number(:P4_ID)) loop',
'  :P4_TITLE               := j.title;',
'  :P4_COMPANY_NAME        := j.company_name;',
'  :P4_LOCATION            := j.location;',
'  :P4_EMPLOYMENT_TYPE     := j.employment_type;',
'  :P4_SALARY_RANGE        := j.salary_range;',
'  :P4_SUBMISSION_DEADLINE := to_char(j.submission_deadline, ''DD-MON-YYYY'');',
'  :P4_SECTOR              := j.sector;',
'  :P4_DESCRIPTION         := j.description;',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P4_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>9459000000000000421
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9459000000000000422)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save Job'
,p_static_id=>'save-job'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_summary fj_jobs.summary%type := case when length(:P4_DESCRIPTION) > 180',
'                                         then substr(:P4_DESCRIPTION, 1, 177) || ''...''',
'                                         else :P4_DESCRIPTION end;',
'begin',
'  if :P4_ID is null then',
'    insert into fj_jobs (title, company_name, location, employment_type, salary_range,',
'                         submission_deadline, sector, summary, description)',
'    values (:P4_TITLE, :P4_COMPANY_NAME, :P4_LOCATION, :P4_EMPLOYMENT_TYPE, :P4_SALARY_RANGE,',
'            to_date(:P4_SUBMISSION_DEADLINE, ''DD-MON-YYYY''), :P4_SECTOR, l_summary, :P4_DESCRIPTION);',
'  else',
'    update fj_jobs',
'       set title = :P4_TITLE, company_name = :P4_COMPANY_NAME, location = :P4_LOCATION,',
'           employment_type = :P4_EMPLOYMENT_TYPE, salary_range = :P4_SALARY_RANGE,',
'           submission_deadline = to_date(:P4_SUBMISSION_DEADLINE, ''DD-MON-YYYY''),',
'           sector = :P4_SECTOR, summary = l_summary, description = :P4_DESCRIPTION',
'     where id = to_number(:P4_ID);',
'  end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>9459000000000000422
);
end;
