,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Download CV'
,p_static_id=>'download-cv'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for a in (select cv_blob, cv_filename, cv_mimetype',
'            from fj_applications',
'           where id = to_number(:P7_ID)',
'             and cv_blob is not null) loop',
'  sys.htp.init;',
'  sys.owa_util.mime_header(nvl(a.cv_mimetype, ''application/octet-stream''), false);',
'  sys.htp.p(''Content-Length: '' || dbms_lob.getlength(a.cv_blob));',
'  sys.htp.p(''Content-Disposition: '' || case when :P7_INLINE = ''Y'' then ''inline'' else ''attachment'' end',
'            || ''; filename="'' || replace(nvl(a.cv_filename, ''cv''), ''"'') || ''"'');',
'  sys.owa_util.http_header_close;',
'  sys.wpg_docload.download_file(a.cv_blob);',
'  apex_application.stop_apex_engine;',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9459000000000000721
);
end;
