,p_process_name=>'Load Screening'
,p_static_id=>'load-screening'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for a in (select a.*, j.salary_range',
'            from fj_applications a join fj_jobs j on j.id = a.job_id',
'           where a.id = to_number(:P8_ID)) loop',
'  :P8_NOTES := a.screening_notes;',
'  :P8_SCORE := coalesce(to_char(a.test_score),',
'                        case when a.test_max_score > 0 then to_char(round(a.test_auto_score / a.test_max_score * 100)) end);',
'  :P8_INT_AT        := to_char(a.interview_at, ''DD-MON-YYYY HH24:MI'');',
'  :P8_INT_MODE      := nvl(a.interview_mode, ''IN_PERSON'');',
'  :P8_INT_LOCATION  := a.interview_location;',
'  :P8_INTERVIEWER   := a.interviewer;',
'  :P8_INT_SCORE     := to_char(a.interview_score);',
'  :P8_INT_NOTES     := a.interview_notes;',
'  :P8_OFFER_SALARY  := nvl(a.offer_salary, a.salary_range);',
'  :P8_OFFER_START   := to_char(a.offer_start_date, ''DD-MON-YYYY'');',
'  :P8_OFFER_MESSAGE := a.offer_message;',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9459000000000000821
);
