'declare',
'  l_email varchar2(255) := lower(trim(:P11_EMAIL));',
'  l_role  varchar2(20);',
'begin',
'  if not fj_auth.authenticate(l_email, :P11_PASSWORD) then',
'    raise_application_error(-20001, ''Invalid email or password.'');',
'  end if;',
'  select role into l_role from fj_users where email = l_email;',
'  -- came from a job''s Apply button: go back to that job so they can apply',
'  if :P11_JOB_ID is not null then',
'    apex_util.set_session_state(''P1_JOB_ID'', :P11_JOB_ID);',
'  end if;',
'  apex_custom_auth.login(',
'      p_uname      => l_email,',
'      p_password   => :P11_PASSWORD,',
'      p_session_id => v(''APP_SESSION''),',
'      p_app_page   => :APP_ID || '':'' || case when l_role = ''ADMIN'' then 5 when :P11_JOB_ID is not null then 1 else 10 end);',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>9459000000000001121
);
