wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9459000000000001421)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Question'
,p_static_id=>'load-question'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for q in (select * from fj_test_questions where id = to_number(:P14_ID)) loop',
'  :P14_JOB_ID   := q.job_id;',
'  :P14_QUESTION := q.question;',
'  :P14_OPTION_A := q.option_a;',
'  :P14_OPTION_B := q.option_b;',
'  :P14_OPTION_C := q.option_c;',
'  :P14_OPTION_D := q.option_d;',
'  :P14_CORRECT  := q.correct_option;',
'  :P14_POINTS   := q.points;',
'end loop;',
':P14_POINTS := nvl(:P14_POINTS, ''1'');'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9459000000000001421
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9459000000000001422)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save Question'
,p_static_id=>'save-question'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_points number := to_number(:P14_POINTS default null on conversion error);',
'  l_seq    number;',
'begin',
'  if (:P14_CORRECT = ''C'' and :P14_OPTION_C is null) or (:P14_CORRECT = ''D'' and :P14_OPTION_D is null) then',
'    raise_application_error(-20001, ''The option marked as correct is empty.'');',
'  end if;',
'  if l_points is null or l_points <= 0 then',
'    raise_application_error(-20001, ''Points must be a number greater than 0.'');',
'  end if;',
'  if :P14_ID is null then',
'    select nvl(max(seq), 0) + 10 into l_seq from fj_test_questions',
'     where (:P14_JOB_ID is null and job_id is null) or job_id = to_number(:P14_JOB_ID);',
'    insert into fj_test_questions (job_id, seq, question, option_a, option_b, option_c, option_d, correct_option, points)',
'    values (to_number(:P14_JOB_ID), l_seq, :P14_QUESTION, :P14_OPTION_A, :P14_OPTION_B, :P14_OPTION_C, :P14_OPTION_D, :P14_CORRECT, l_points);',
'  else',
'    update fj_test_questions',
'       set job_id = to_number(:P14_JOB_ID), question = :P14_QUESTION, option_a = :P14_OPTION_A, option_b = :P14_OPTION_B,',
'           option_c = :P14_OPTION_C, option_d = :P14_OPTION_D, correct_option = :P14_CORRECT, points = l_points',
'     where id = to_number(:P14_ID);',
'  end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>9459000000000001422
);
end;
