'  sys.htp.p(''Content-Disposition: attachment; filename="'' || replace(nvl(a.offer_letter_filename, ''offer-letter''), ''"'') || ''"'');',
'  sys.owa_util.http_header_close;',
'  sys.wpg_docload.download_file(a.offer_letter);',
'  apex_application.stop_apex_engine;',
