'    raise_application_error(-20001, ''Invalid email or password.'');',
'  end if;',
'  select role into l_role from fj_users where email = l_email;',
'  -- employers land on the dashboard, job seekers on My Applications',
'  apex_custom_auth.login(',
'      p_uname      => l_email,',
'      p_password   => :P9999_PASSWORD,',
'      p_session_id => v(''APP_SESSION''),',
'      p_app_page   => :APP_ID || '':'' || case when l_role = ''ADMIN'' then 5 else 10 end);',
'end;'))
